import { tt } from '../i18n';
import { useEffect, useRef, useState } from 'react';
import { Link, useParams, useSearchParams } from 'react-router-dom';
import { api, ApiError, newIdempotencyKey, commandApi, describeError, parseNum } from '../api';
import { checkDto, DTO } from '../dto';
import { useLoad, getJson, useReconciler } from '../hooks';
import { usePerms } from '../permissions';
import { trl } from '../labels';
import { Field } from '../../components/Field';
import { Button } from '../../components/Button';
import { Kicker } from '../../components/Kicker';
import { AiAssist, PreviewAi, ActionAiPlan } from './AiPlan';

export const useTid = () => useParams().tid as string;
export const fmt = (v: number | null | undefined, d = 1) => v === null || v === undefined ? '—' : Number(v).toLocaleString('tr-TR', { minimumFractionDigits: d, maximumFractionDigits: d });
export type Cycle = { id: string; code: string; active_batch_id: string | null; status: string };
export type Unit = { id: string; code: string; name: string; result_rows: number };
export function useCyclesUnits(tid: string) {
  const [sp] = useSearchParams(); const qCycle = sp.get('cycle') ?? '', qUnit = sp.get('unit') ?? ''; // V25/F11: bağlantı bağlamı seçili açılır
  const [cycle, setCycle] = useState<string>(''); const [unit, setUnit] = useState<string>('');
  const cq = useLoad<Cycle[]>(tid ? `c|${tid}|${qCycle}` : null, getJson<Cycle[]>(`/api/t/${tid}/cycles`, DTO.cycles));
  useEffect(() => { const c = cq.data; if (!c) return; const pub = (qCycle && c.find(x => x.id === qCycle)) || c.find(x => x.active_batch_id) || c[0]; setCycle(pub ? pub.id : ''); }, [cq.data]);
  const uq = useLoad<Unit[]>(tid && cycle ? `u|${tid}|${cycle}` : null, getJson<Unit[]>(`/api/t/${tid}/cycles/${cycle}/units`, DTO.units));
  useEffect(() => { const u = uq.data; if (!u) return; setUnit(prev => (u.some(x => x.id === prev) ? prev : (qUnit && u.some(x => x.id === qUnit)) ? qUnit : ((u.find(x => x.result_rows > 0) || u[0])?.id ?? ''))); }, [uq.data]);
  const failed = cq.status === 'error' ? cq : uq.status === 'error' ? uq : null;
  const unitOk = !!unit && (uq.data ?? []).some(x => x.id === unit);
  return { cycles: cq.data ?? [], cycle, setCycle, units: uq.data ?? [], unit, setUnit, ready: !!cycle && unitOk, key: `${tid}|${cycle}|${unit}`, loading: cq.status === 'loading' || uq.status === 'loading', loadErr: failed ? failed.message : null, retry: () => { void cq.reload(); void uq.reload(); }, empty: uq.status === 'ok' && (uq.data ?? []).length === 0 };
}
/** F10: yükleme hatası — servis/ağ/yetki mesajı ve kontrollü yeniden deneme; boş veri gibi gösterilmez */
/** N02: yetki bilgisi alınamadıysa işlem düğmeleri kapalıdır; kullanıcı nedenini ve yeniden deneme yolunu görür */
export function PermNotice({ perms }: { perms: { status: string; message: string | null; reload: () => unknown } }) { return perms.status === 'error' ? <div className="col-12"><LoadError message={tt("Yetki bilgisi alınamadı; işlem düğmeleri kapalı. {0}", perms.message ?? '')} retry={() => { void perms.reload(); }} /></div> : null; }
export function LoadError({ message, retry }: { message: string; retry?: () => void }) { return <div className="notice stack-1"><p className="bold">{message}</p>{retry ? <button type="button" className="link caption" onClick={retry}>{tt("Yeniden dene")}</button> : null}</div>; }
export function ContextStatus({ s }: { s: ReturnType<typeof useCyclesUnits> }) { if (s.loadErr) return <div className="col-12"><LoadError message={s.loadErr} retry={s.retry} /></div>; if (s.loading && !s.ready) return <div className="col-12"><p className="caption">{tt("Yükleniyor…")}</p></div>; if (s.empty) return <div className="col-12"><p className="caption">{tt("Bu dönemde görebileceğiniz birim yok.")}</p></div>; return null; }
export function Pickers({ s }: { s: ReturnType<typeof useCyclesUnits> }) { return <div className="row"><div style={{ width: '16ch' }}><Field id="cycle" kind="select" label={tt("Dönem")} value={s.cycle} onChange={e => s.setCycle(e.target.value)}>{s.cycles.map(c => <option key={c.id} value={c.id}>{c.code}{c.active_batch_id ? '' : tt(" (sonuç yok)")}</option>)}</Field></div><div style={{ minWidth: '26ch' }}><Field id="unit" kind="select" label={tt("Birim")} value={s.unit} onChange={e => s.setUnit(e.target.value)}>{s.units.map(u => <option key={u.id} value={u.id}>{u.code} · {u.name}{u.result_rows ? '' : tt(" (sonuç yok)")}</option>)}</Field></div></div>; }
export type Row = { resultId: string; metricCode: string; itemCode: string; text: string; dimensionCode: string | null; dimensionName: string | null; origin: string; n: number | null; value: number | null; suppressed: boolean; status: string; revision: number; companyValue: number | null; benchmarkCertified: number | null; interactionArea: string; responsibilityLabel: string; targetPolicy: string; candidateRoles: { id: string; code: string; title: string }[]; confirmationRequired: boolean; assessment: { decision: string; tier: string; confidenceLabel: string; rankKey: number } | null };
export const DEC: Record<string, string> = { numeric_target_and_actions: tt("Sayısal hedef + aksiyon"), validation_required: tt("Doğrulama gerekli"), recommended_target: tt("Önerilen hedef"), monitor: tt("İzle"), no_action: tt("Hedef yok") };
export const AREA: Record<string, string> = { work: tt("işim"), manager: tt("yöneticim"), colleagues: tt("çalışma arkadaşlarım"), employer_brand: tt("işveren markası"), system: tt("sistem / politika"), self: tt("kişisel eğilim"), outcome: tt("sonuç") };

export function UnitResults() {
  const tid = useTid(); const s = useCyclesUnits(tid);
  // F01: sonuç yalnız güncel şirket|dönem|birim anahtarına aitse gösterilir; eski istek iptal edilir, geç gelen yanıt yok sayılır
  const rq = useLoad<{ cycle: { code: string; batchId: string }; unit: { name: string; code: string }; rows: Row[] }>(s.ready ? `r|${s.key}` : null, getJson(`/api/t/${tid}/cycles/${s.cycle}/units/${s.unit}/results`, DTO.results)); const data = rq.data; const err = rq.status === 'error' ? rq.message : null;
  const dims = data ? [...new Map(data.rows.map(r => [r.dimensionCode ?? '', r.dimensionName ?? 'Boyutsuz'])).entries()] : [];
  const tb = (data?.rows ?? []).filter(r => r.metricCode.endsWith('_TB'));
  return (
    <main><section className="section surface-white"><div className="container grid">
      <div className="col-12 row row--between"><Kicker>{tt("Birim sonuçları · madde düzeyi · Top Box")}</Kicker><Pickers s={s} /></div>
      <ContextStatus s={s} />
      {err ? <div className="col-12"><LoadError message={err} retry={() => { void rq.reload(); }} /></div> : null}{rq.status === 'loading' ? <div className="col-12"><p className="caption">{tt("Sonuçlar yükleniyor…")}</p></div> : null}{data && data.rows.length === 0 ? <div className="col-12"><p className="caption">{tt("Bu birim ve dönem için yayımlanmış sonuç yok.")}</p></div> : null}
      {data && data.rows.length ? <>
        <div className="col-12 stack-1"><h1 className="h2">{data.unit.name} · {data.cycle.code} · {tb.length} {tt("madde")}{tb.every(r => r.suppressed) ? tt(" · yanıt sayısı eşiğin altında: sayı gösterilmez") : ''}</h1><p className="caption">{tt("Şirket Δ: birimin değeri − şirket geneli (yanıt ağırlıklı). Karar maddeye göre; \"müdahaleye yetkili\" sorumluluk merkezinden gelen aday roldür, teyit gerekebilir.")}</p></div>
        {dims.map(([dc, dn]) => { const rows = data.rows.filter(r => (r.dimensionCode ?? '') === dc); return <div key={dc} className="col-12 stack-1"><Kicker>{dn}</Kicker><div className="table-wrap"><table className="table"><thead><tr><th>{tt("Madde")}</th><th>{tt("Metrik")}</th><th className="num">{tt("Değer")}</th><th className="num">{tt("Şirket Δ")}</th><th className="num">{tt("n")}</th><th>{tt("Etkileşim")}</th><th>{tt("Sorumluluk merkezi")}</th><th>{tt("Aday rol")}</th><th>{tt("Karar")}</th></tr></thead><tbody>{rows.map(r => <tr key={r.metricCode}><td>{r.text}<span className="caption"> · {r.itemCode}</span></td><td className="caption" style={{ whiteSpace: 'nowrap' }}>{r.metricCode.endsWith('_NPS') ? tt("NPS") : tt("Top Box")}</td><td className="num bold">{r.suppressed ? '—' : fmt(r.value)}</td><td className="num">{r.suppressed || r.companyValue === null ? '—' : fmt((r.value ?? 0) - r.companyValue)}</td><td className="num">{r.suppressed || r.n === null ? '—' : r.n}</td><td className="caption">{AREA[r.interactionArea] ?? r.interactionArea}</td><td className="caption">{r.responsibilityLabel}</td><td className="caption">{r.candidateRoles.map(c => c.title).join(', ') || '—'}{r.confirmationRequired ? tt(" (teyit)") : ''}</td><td className="caption">{r.assessment ? DEC[r.assessment.decision] ?? r.assessment.decision : r.suppressed ? tt("gizli") : '—'}</td></tr>)}</tbody></table></div></div>; })}
      </> : null}
      <div className="col-12"><OfficialAggregates tid={tid} cycleId={s.cycle} unitId={s.unit} /></div>
    </div></section></main>
  );
}
export type Target = { id: string; baseline_superseded?: boolean; item_code: string; item_text: string; kind: string; baseline_score: number | null; suggested_target: number | null; lower_feasible: number | null; upper_feasible: number | null; approved_target: number | null; /* F08: gizlilik eşiği altında null */ source: string; status: string; version: number; actions: number; rationale: string };
export function Targets() {
  const tid = useTid(); const s = useCyclesUnits(tid); const perms = usePerms(tid, s.ready ? s.unit : null); const [sp] = useSearchParams(); const qTarget = sp.get('target') ?? ''; const [item, setItem] = useState(''); const [val, setVal] = useState(''); const [valErr, setValErr] = useState<string | null>(null); const [err, setErr] = useState<string | null>(null); const [msg, setMsg] = useState<string | null>(null);
  // F01/F10: sonuç ve hedef listesi bağlam anahtarıyla; hata boş liste gibi gösterilmez
  const lq = useLoad<{ rows: Row[]; targets: Target[] }>(s.ready ? `t|${s.key}` : null, async signal => { const d = checkDto<{ rows: Row[] }>(await api('GET', `/api/t/${tid}/cycles/${s.cycle}/units/${s.unit}/results`, undefined, { signal }), DTO.results, '/results'); const t = checkDto<Target[]>(await api('GET', `/api/t/${tid}/cycles/${s.cycle}/units/${s.unit}/targets`, undefined, { signal }), DTO.targets, '/targets'); return { rows: d.rows, targets: t }; });
  const rows = (lq.data?.rows ?? []).filter(r => r.metricCode.endsWith('_TB') && !r.suppressed && r.targetPolicy !== 'MONITOR_ONLY').sort((a, b) => (b.assessment?.rankKey ?? 0) - (a.assessment?.rankKey ?? 0)); const targets = lq.data?.targets ?? [];
  const load = async () => { await lq.reload(); }; useReconciler(async () => { if (!(await lq.reload())) throw new ApiError(0, 'network', tt("Kayıt yeniden okunamadı")); }, s.key);
  useEffect(() => { setItem(''); setVal(''); setValErr(null); setErr(null); setMsg(null); }, [s.key]); // F02: bağlam değişince form temizlenir
  const linked = qTarget && lq.status === 'ok' ? targets.find(t => t.id === qTarget) ?? null : null;
  const [pv, setPv] = useState<{ proposal: { low: number; high: number; target: number; source: string }; confirmationRequired: boolean; candidateRoles: { code: string; title: string }[]; measurementPlan: { followupCycleCode: string | null; horizonDays: number }; monitoringRole: string } | null>(null);
  useEffect(() => { setPv(null); }, [item, s.key]);
  const [aiPreviewPlan, setAiPreviewPlan] = useState<string | null>(null); // v2.13.1: hedef öncesi AI planı (hedef oluşturulunca bağlanır)
  // R14: öneri → önizleme (kayıt yazmaz) → kabul; hedef tarihi ve takip dönemi kabulden önce görülür
  const preview = async () => { setErr(null); setMsg(null); const k = s.key; try { const r = await api<typeof pv>('POST', `/api/t/${tid}/cycles/${s.cycle}/units/${s.unit}/targets?preview=1`, { itemCode: item }); if (k === s.key) setPv(r); } catch (e) { setErr(describeError(e)); } };
  const [ikey, setIkey] = useState(newIdempotencyKey()); useEffect(() => { setIkey(newIdempotencyKey()); }, [item, val, s.cycle, s.unit]);
  const create = async () => { setErr(null); setMsg(null); const nv = parseNum(val, { min: 0, max: 100, label: tt("Hedef değer") }); if (!nv.ok) { setValErr(nv.error); return; } setValErr(null); try { const r = await api<{ id?: string; status: string; proposal: { low: number; high: number; target: number; source: string }; confirmationRequired: boolean }>('POST', `/api/t/${tid}/cycles/${s.cycle}/units/${s.unit}/targets`, { itemCode: item, ...(nv.value !== null ? { target: nv.value } : {}) }, { idempotencyKey: ikey }); setIkey(newIdempotencyKey());
    if (aiPreviewPlan && r.id) { try { await api('POST', `/api/t/${tid}/ai-plans/${aiPreviewPlan}/bind`, { targetId: r.id }, { idempotencyKey: newIdempotencyKey() }); } catch { /* bağlama başarısızsa hedef yine oluşmuştur; plan önizlemede kalır */ } } setMsg(tt("{0}: {1} (aralık {2}–{3}, dayanak {4}){5}", r.status === 'under_review' ? 'İnceleme bekliyor' : 'Kabul edildi', fmt(r.proposal.target), fmt(r.proposal.low), fmt(r.proposal.high), r.proposal.source === 'peer_history' ? 'akran geçmişi' : 'metodolog bandı', r.confirmationRequired ? ' · müdahaleye yetkili rol teyit gerektirir' : '')); setPv(null); await load(); } catch (e) { setErr(describeError(e)); } };
  const review = async (id: string, decision: 'accept' | 'reject', superseded = false) => { const reason = prompt(decision === 'accept' ? tt("Kabul gerekçesi") : tt("Ret gerekçesi")); if (!reason || reason.trim().length < 3) return; let baseline: 'keep' | 'rebase' | undefined; if (decision === 'accept' && superseded) { baseline = confirm(tt("Başlangıç sonucu düzeltildi. Tamam = düzeltilmiş başlangıçtan yeniden öner; İptal = eski taahhüdü koru")) ? 'rebase' : 'keep'; } try { await commandApi(`/api/t/${tid}/targets/${id}/review`, { decision, reason: reason.trim(), ...(baseline ? { baseline } : {}) }); await load(); } catch (e) { const a = e as ApiError; if (['receipt_lost', 'receipt_lost_unverified'].includes(a.code)) setMsg(a.message); else setErr(describeError(e)); await load(); } };
  // F09: hedef sorumlusunun devri (İK yöneticisi / İK iş ortağı) — rol kodu ve gerekçe; vazgeçilebilir; sonuç ve tarihçe gösterilir
  const [hist, setHist] = useState<{ id: string; rows: { created_at: string; from_role_code: string | null; to_role_code: string | null; reason: string }[] } | null>(null);
  const showHistory = async (id: string) => { try { setHist({ id, rows: await api('GET', `/api/t/${tid}/ownership-history/local_target/${id}`) }); } catch (e) { setErr(describeError(e)); } };
  const transfer = async (t: Target) => { const toRoleCode = prompt(tt("“{0}” hedefinin sorumlusu hangi role devredilsin? (rol kodu; vazgeçmek için İptal)", t.item_code)); if (toRoleCode === null) return; if (toRoleCode.trim().length < 2) { setErr(tt("Rol kodu girilmedi; devir yapılmadı")); return; } const reason = prompt(tt("Devir gerekçesi (en az 5 karakter; vazgeçmek için İptal)")); if (reason === null) return; if (reason.trim().length < 5) { setErr(tt("Devir gerekçesi en az 5 karakter olmalıdır; devir yapılmadı")); return; } setErr(null); setMsg(null); try { const r = await commandApi<{ fromRole: string | null; toRole: string | null }>(`/api/t/${tid}/targets/${t.id}/transfer`, { toRoleCode: toRoleCode.trim(), reason: reason.trim() }); setMsg(tt("Hedef sorumlusu devredildi: {0} → {1}", r.fromRole ?? 'atanmamış', r.toRole)); await load(); await showHistory(t.id); } catch (e) { const a = e as ApiError; if (['receipt_lost', 'receipt_lost_unverified'].includes(a.code)) setMsg(a.message); else setErr(describeError(e)); } };
  return (
    <main><section className="section surface-white"><div className="container grid">
      <ContextStatus s={s} />{lq.status === 'error' ? <div className="col-12"><LoadError message={lq.message ?? ''} retry={() => { void lq.reload(); }} /></div> : null}{qTarget && lq.status === 'ok' ? <div className="col-12"><p className="caption">{linked ? <>{tt("Bağlantıdaki hedef:")}{' '}<span className="bold">{linked.item_code} · {linked.item_text}</span> ({trl(linked.status)})</> : tt("Bağlantıdaki hedef bu birim ve dönemde bulunamadı; kapatılmış, taşınmış ya da yetkiniz dışında olabilir.")}</p></div> : null}
      <PermNotice perms={perms} /><div className="col-12 row row--between"><Kicker>{tt("Yerel gelişim hedefleri · madde düzeyi · en fazla 2")}</Kicker><Pickers s={s} /></div>
      <div className="col-7 stack"><div className="table-wrap"><table className="table"><thead><tr><th>{tt("Madde")}</th><th className="num">{tt("Başlangıç")}</th>{perms.can('createTarget') ? <th className="num">{tt("Aralık")}</th> : null}<th className="num">{tt("Hedef")}</th><th>{tt("Dayanak")}</th><th>{tt("Durum")}</th><th className="num">{tt("Aksiyon")}</th><th></th></tr></thead><tbody>{targets.map(t => <tr key={t.id}><td>{t.item_text}<span className="caption"> · {t.item_code}</span></td><td className="num">{fmt(t.baseline_score)}</td>{perms.can('createTarget') ? <td className="num">{fmt(t.lower_feasible)}–{fmt(t.upper_feasible)}</td> : null}<td className="num bold">{fmt(t.approved_target ?? t.suggested_target)}</td><td className="caption">{t.source}</td><td className="caption">{trl(t.status)} {tt("v")}{t.version}</td><td className="num">{t.actions}</td><td>{t.status === 'under_review' && perms.can('reviewTarget') ? <><button type="button" className="link caption" onClick={() => review(t.id, 'accept', !!t.baseline_superseded)}>{tt("onayla")}</button> · <button type="button" className="link caption" onClick={() => review(t.id, 'reject')}>{tt("reddet")}</button></> : ['accepted', 'active'].includes(t.status) ? <><Link className="link caption" to={`/t/${tid}/aksiyonlar?unit=${s.unit}&cycle=${s.cycle}&target=${t.id}`}>{tt("aksiyon")}</Link>{perms.can('transferTarget') ? <> · <button type="button" className="link caption" onClick={() => transfer(t)}>{tt("sorumluyu devret")}</button> · <button type="button" className="link caption" onClick={() => showHistory(t.id)}>{tt("tarihçe")}</button></> : null}</> : t.status === 'pending_acceptance' && perms.can('acceptTarget') ? <><span className="caption">{tt("yeni öneri")}{' '}{fmt(t.suggested_target)} ({fmt(t.lower_feasible)}–{fmt(t.upper_feasible)}{tt(") · sürüm")}{' '}{t.version}</span> · <button type="button" className="link caption" onClick={async () => { const v = prompt(tt("Yeni öneri {0} (aralık {1}–{2}). Kabul edilecek hedef (boş: öneri)", fmt(t.suggested_target), fmt(t.lower_feasible), fmt(t.upper_feasible))); if (v === null) return; const nv = parseNum(v, { min: 0, max: 100, label: tt("Kabul edilecek hedef") }); if (!nv.ok) { setErr(nv.error); return; } const reason = prompt(tt("Kabul gerekçesi (isteğe bağlı)")) ?? ''; try { await commandApi(`/api/t/${tid}/targets/${t.id}/accept`, { expectedVersion: t.version, ...(nv.value !== null ? { target: nv.value } : {}), ...(reason.trim() ? { reason: reason.trim() } : {}) }); await load(); } catch (e) { const a = e as ApiError; setErr(a.code === 'version_changed' ? tt("Taslak sizin gördüğünüz sürümden sonra değişti; liste yenilendi, güncel öneriyi inceleyin") : a.message); await load(); } }}>{tt("taslağı kabul et")}</button> · <button type="button" className="link caption" onClick={async () => { const reason = prompt(tt("Ret gerekçesi (zorunlu)")); if (!reason || reason.trim().length < 3) return; try { await commandApi(`/api/t/${tid}/targets/${t.id}/accept`, { expectedVersion: t.version, decision: 'reject', reason: reason.trim() }); await load(); } catch (e) { const a = e as ApiError; setErr(a.code === 'version_changed' ? tt("Taslak değişti; liste yenilendi") : a.message); await load(); } }}>{tt("gerekçeli reddet")}</button></> : null}</td></tr>)}{lq.status === 'ok' && targets.length === 0 ? <tr><td colSpan={8} className="caption">{tt("Bu birimde hedef yok")}</td></tr> : null}</tbody></table></div>
        <p className="caption">{tt("Hedef bir anket maddesine konur; sonucu izleyen rol birim yöneticisi, müdahaleye yetkili rol maddenin sorumluluk merkezinden gelir. Bağlılık ve kişisel eğilim maddeleri izleme göstergesidir. Aralık dışı için istisna, inceleme gerektiren maddelerde İK onayı.")}</p></div>
      {perms.can('createTarget') ? <div className="col-5 stack"><Kicker>{tt("Yeni hedef")}</Kicker>
        <Field id="item" kind="select" label={tt("Madde (öncelik sırasıyla)")} value={item} onChange={e => setItem(e.target.value)}><option value="">{tt("seçin")}</option>{rows.map(r => <option key={r.itemCode} value={r.itemCode}>{r.itemCode} · {fmt(r.value)} · {r.assessment ? DEC[r.assessment.decision] : ''} · {r.text.slice(0, 60)}</option>)}</Field>
        <Field id="val" label={tt("Hedef değer (boş: sistem önerisi)")} value={val} inputMode="decimal" error={valErr ?? undefined} onChange={e => { setVal(e.target.value); setValErr(null); }} />
        <div className="row"><Button variant="secondary" onClick={preview} disabled={!item}>{tt("Öneriyi gör")}</Button><Button onClick={create} disabled={!item || !pv}>{tt("Öneriyi kabul et")}</Button></div>
        {pv ? <div className="stack-1 ai-oneri" data-testid="hedef-oneri"><p className="body"><span className="bold">{tt("Önerilen hedef aralığı:")}</span> %{fmt(pv.proposal.low)}–%{fmt(pv.proposal.high)}{' · '}<span className="bold">{tt("Sistem önerisi:")}</span> {fmt(pv.proposal.target)}</p><p className="caption">{tt("Mevcut sonuç ve HPW metodolojisine göre gerçekçi kabul edilen hedef aralığıdır.")}{' '}{tt("Takip dönemi:")}{' '}{pv.measurementPlan.followupCycleCode ?? tt("sonraki dönem")}{' · '}{tt("takip süresi {0} gün", pv.measurementPlan.horizonDays)}{' · '}{tt("izleyen rol:")}{' '}{pv.monitoringRole}{pv.candidateRoles.length ? <>{' · '}{tt("müdahaleye yetkili:")}{' '}{pv.candidateRoles.map(c => c.title).join(', ')}</> : null}</p></div> : null}
        {pv && item ? <PreviewAi tid={tid} cycleId={s.cycle} unitId={s.unit} itemCode={item} range={{ low: pv.proposal.low, high: pv.proposal.high }} onUseTarget={v => { setVal(String(v)); setValErr(null); }} onPlan={setAiPreviewPlan} /> : null}
        {err ? <p className="bold">{err}</p> : null}{msg ? <p className="caption">{msg}</p> : null}</div> : <div className="col-5 stack">{err ? <p className="bold">{err}</p> : null}{msg ? <p className="caption">{msg}</p> : null}{hist ? null : null}</div>}
      {hist ? <div className="col-12 stack-1"><Kicker>{tt("Sorumlu devri tarihçesi")}</Kicker><table className="table"><thead><tr><th>{tt("Tarih")}</th><th>{tt("Önceki rol")}</th><th>{tt("Yeni rol")}</th><th>{tt("Gerekçe")}</th></tr></thead><tbody>{hist.rows.map((h, k) => <tr key={k}><td className="caption">{String(h.created_at).slice(0, 16).replace('T', ' ')}</td><td>{h.from_role_code ?? '—'}</td><td>{h.to_role_code ?? '—'}</td><td className="caption">{h.reason}</td></tr>)}{hist.rows.length === 0 ? <tr><td colSpan={4} className="caption">{tt("Bu hedef için devir kaydı yok.")}</td></tr> : null}</tbody></table></div> : null}
      <AiAssist tid={tid} targets={lq.status === 'ok' ? targets : []} canUse={perms.can('createTarget')} />
      <div className="col-12"><CohortDecisions tid={tid} unitId={s.unit} /></div>
    </div></section></main>
  );
}
export type Action = { id: string; title: string; unit_id: string; unit_code: string; unit_name: string; lifecycle_state: string; from_ai_plan?: boolean; verification_state: string; health_state: string; evidence_level: string; verification_route: string; requirement: { expected: number; windowStart: string; windowEnd: string; cadence: string; label: string; attendanceRequired?: boolean; slots?: string[] }; start_date: string; due_date: string; version: number; targets: { targetId: string; itemCode: string }[] | null; valid_evidence: number; fulfilled_slots: number };
