export function Followup() {
  const tid = useTid(); const s = useCyclesUnits(tid); const [targets, setTargets] = useState<Target[]>([]); const [fu, setFu] = useState(''); const [sel, setSel] = useState<string | null>(null); const [res, setRes] = useState<Record<string, unknown> | null>(null); const [err, setErr] = useState<string | null>(null); const seq = useRef(0);
  // seçim değişince eski değerlendirme temizlenir; geç dönen yanıt yeni bağlama taşınmaz (R09)
  useEffect(() => { setRes(null); setSel(null); setErr(null); seq.current++; if (!s.cycle || !s.unit) { setTargets([]); return; } api<Target[]>('GET', `/api/t/${tid}/cycles/${s.cycle}/units/${s.unit}/targets`).then(t => setTargets(t.filter(x => ['accepted', 'active', 'under_review', 'pending_acceptance'].includes(x.status)))).catch(() => setTargets([])); }, [tid, s.cycle, s.unit]);
  useEffect(() => { setRes(null); setSel(null); seq.current++; }, [fu]);
  const run = async (id: string) => { setErr(null); setSel(id); setRes(null); const my = ++seq.current; try { const r = await commandApi<Record<string, unknown>>(`/api/t/${tid}/targets/${id}/followup/assess`, { cycleId: fu }); if (my !== seq.current) return; setRes(r); } catch (e) { if (my === seq.current) setErr(describeError(e)); } };
  // onay/ret yalnız seçili hedefin kimliğiyle gider; liste sırası belirleyici değildir (R08)
  const review = async (decision: string) => { if (!sel || !res || res.targetId !== sel) { setErr(tt("Seçili hedef ile değerlendirme uyuşmuyor; yeniden değerlendirin")); return; } const comp = (res.comparability as { version: string }); const fol = res.followup as { revision: number }; try { await commandApi(`/api/t/${tid}/targets/${sel}/followup/review`, { cycleId: fu, decision, comparabilityVersion: comp.version, resultVersion: `R${fol.revision}` }); await run(sel); } catch (e) { setErr(describeError(e)); } };
  const st = res ? (res.status as string | undefined) : undefined; const out = res?.outcome as { status: string; attainment?: string; observedChange?: number; observedAboveTarget?: boolean; attributionEvidenceGrade?: string } | undefined; const comp = res?.comparability as { status: string; level: string; itemEquivalence?: string } | undefined; const base = res?.baseline as { value: number | null; n: number; suppressed?: boolean } | undefined; const fol = res?.followup as { value: number | null; n: number; suppressed?: boolean; cycle: string } | undefined; const selT = targets.find(t => t.id === sel);
  return (
    <main><section className="section surface-white"><div className="container grid">
      <div className="col-12 row row--between"><Kicker>{tt("Takip ölçümü · aynı birim ve madde, sonraki dönem")}</Kicker><Pickers s={s} /></div>
      <div className="col-5 stack"><Field id="fu" kind="select" label={tt("Takip dönemi")} value={fu} onChange={e => setFu(e.target.value)}><option value="">{tt("seçin")}</option>{s.cycles.filter(c => c.id !== s.cycle && c.active_batch_id).map(c => <option key={c.id} value={c.id}>{c.code}</option>)}</Field>
        <table className="table"><thead><tr><th>{tt("Hedef")}</th><th className="num">{tt("Başlangıç → hedef")}</th><th></th></tr></thead><tbody>{targets.map(t => <tr key={t.id} className={t.id === sel ? 'bold' : ''}><td>{t.item_code}{t.status === 'under_review' ? tt(" · incelemede") : t.status === 'pending_acceptance' ? tt(" · kabul bekliyor") : ''}</td><td className="num">{fmt(t.baseline_score)} → {fmt(t.approved_target)}</td><td><button type="button" className="link caption" disabled={!fu} onClick={() => run(t.id)}>{t.id === sel ? tt("seçili") : tt("değerlendir")}</button></td></tr>)}{targets.length === 0 ? <tr><td colSpan={3} className="caption">{tt("Bu birim ve dönemde kabul edilmiş hedef yok.")}</td></tr> : null}</tbody></table>{err ? <p className="bold">{err}</p> : null}</div>
      <div className="col-7 stack">{!res ? <p className="caption">{sel ? tt("Değerlendiriliyor…") : tt("Takip dönemini seçip bir hedefi değerlendirin.")}</p>
        : st === 'NOT_MEASURED' ? <><Kicker>{tt("Ölçülmedi ·")}{' '}{selT?.item_code}</Kicker><p className="body-l">{String(res.reason)}</p><p className="caption">{tt("Takip döneminde bu madde sorulmadı ya da bu birim için sonuç yüklenmedi. Değerlendirme yapılamaz; hedef açık kalır.")}</p></>
        : res.hidden === true || st === 'HIDDEN' ? <><Kicker>{tt("Gizli ·")}{' '}{selT?.item_code}</Kicker><p className="body-l">{tt("Başlangıç ya da takip sonucu gizlilik eşiğinin altında; sayı, n, hedef ve karşılaştırma gösterilmez (HPW gizlilik politikası v1).")}</p></>
        : st === 'NOT_COMMITTED' ? <><Kicker>{tt("Kabul edilmiş taahhüt yok ·")}{' '}{selT?.item_code}</Kicker><p className="body-l">{String(res.reason)} {tt("(hedef durumu:")}{' '}{String(res.targetStatus)}).</p>{res.observed ? <p className="caption">{tt("Gözlem: başlangıç")}{' '}{fmt((res.observed as { baseline: number }).baseline)} {tt("→ takip")}{' '}{fmt((res.observed as { followup: number }).followup)} {tt("(n")}{' '}{(res.observed as { n: number }).n}{tt("), değişim")}{' '}{fmt((res.observed as { change: number }).change)}{tt(". Bu bir ulaşma kararı değildir; taslağı Hedefler ekranından kabul edin ya da gerekçeyle reddedin.")}</p> : null}</>
        : st === 'UNDER_REVIEW' ? <><Kicker>{tt("İncelemede ·")}{' '}{selT?.item_code}</Kicker><p className="body-l">{String(res.reason)}</p></>
        : selT?.status === 'under_review' ? <><Kicker>{tt("İncelemede ·")}{' '}{selT.item_code}</Kicker><p className="body-l">{tt("Hedefin başlangıcı düzeltildi ya da metodoloji incelemesi bekliyor; takip kararı için önce Hedefler ekranında inceleme tamamlanmalı.")}</p></>
        : (base?.suppressed || fol?.suppressed) ? <><Kicker>{tt("Gizli ·")}{' '}{selT?.item_code}</Kicker><p className="body-l">{tt("Başlangıç ya da takip sonucu gizlilik eşiğinin altında; sayı, n ve karşılaştırma gösterilmez (HPW gizlilik politikası v1).")}</p></>
        : <>
        <Kicker>{out?.status} {tt("· ulaşma:")}{' '}{out?.attainment} {tt("· karşılaştırılabilirlik:")}{' '}{comp?.status} ({comp?.level}{comp?.itemEquivalence ? tt(", madde: ") + comp.itemEquivalence : ''})</Kicker>
        <p className="body-l">{tt("Başlangıç")}{' '}{fmt(base?.value)} {tt("(n")}{' '}{base?.n}{tt(") → takip")}{' '}{fmt(fol?.value)} {tt("(n")}{' '}{fol?.n}, {fol?.cycle}{tt(") · hedef")}{' '}{fmt(res.target as number)} {tt("· gözlenen değişim")}{' '}{fmt(out?.observedChange)} {tt("· gözlem hedefin")}{' '}{out?.observedAboveTarget === true ? tt("üstünde") : out?.observedAboveTarget === false ? tt("altında") : tt("karşılaştırması yapılamadı")} {tt("· atıf derecesi")}{' '}{out?.attributionEvidenceGrade ?? '—'} {tt("(nedensel iddia yok)")}</p>
        {out?.status === 'PENDING_REVIEW' ? <div className="row"><Button onClick={() => review('comparable_labeled')}>{tt("Karşılaştırılabilir (etiketli) onayla ·")}{' '}{selT?.item_code}</Button><Button variant="secondary" onClick={() => review('not_comparable')}>{tt("Karşılaştırılamaz ·")}{' '}{selT?.item_code}</Button></div> : null}
        <p className="caption">{tt("İnceleme onayı yalnız aynı sonuç revizyonu ve karşılaştırılabilirlik sürümüyle geçerlidir; sonuç düzeltilirse onay düşer. Yalnız İK yetkilileri onaylar.")}</p></>}</div>
    </div></section></main>
  );
}
export function Attention() {
  const tid = useTid(); const [items, setItems] = useState<{ id: string; kind: string; severity: string; title: string; route: string; unitId?: string | null; cycleId?: string | null; entityId?: string }[]>([]); const [err, setErr] = useState<string | null>(null);
  const read = async () => { setItems(checkDto<typeof items>(await api('GET', `/api/t/${tid}/attention`), DTO.attention, '/attention')); setErr(null); }; const load = () => read().catch(e => setErr(describeError(e))); useReconciler(read, tid);
  useEffect(() => { void load(); }, [tid]);
  const snooze = async (id: string) => { const until = prompt(tt("Hangi tarihe kadar ertelensin? (YYYY-AA-GG)")); if (!until) return; try { await commandApi(`/api/t/${tid}/attention/${encodeURIComponent(id)}/snooze`, { until }); await load(); } catch (e) { setErr(describeError(e)); } };
  const routes: Record<string, string> = { results: 'donemler', users: 'kullanicilar', targets: 'hedefler', actions: 'aksiyonlar' };
  return (
    <main><section className="section surface-white"><div className="container grid">
      <div className="col-12"><Kicker>{tt("Bekleyen işleriniz")}</Kicker>{items.length ? <h1 className="h1">{tt("{0} konu sizi bekliyor", items.length)}</h1> : <h1 className="h1" data-testid="dikkat-bos">{tt("Şu anda bekleyen işiniz bulunmuyor.")}</h1>}<p className="caption">{tt("Bir konu, asıl işlem (yayım, gönderim, karar, kanıt) yapılınca kendiliğinden kapanır. Ertelemek yükümlülüğü kaldırmaz.")}</p></div>
      <div className="col-12"><table className="table"><thead><tr><th>{tt("Önem")}</th><th>{tt("Konu")}</th><th></th></tr></thead><tbody>{items.map(i => <tr key={i.id}><td className={i.severity === 'critical' ? 'bold' : 'caption'}>{trl(i.severity)}</td><td>{i.title}</td><td><Link className="link caption" to={`/t/${tid}/${routes[i.route] ?? ''}${i.unitId ? `?unit=${i.unitId}${i.cycleId ? '&cycle=' + i.cycleId : ''}${i.entityId ? (i.route === 'actions' ? '&action=' : i.route === 'targets' ? '&target=' : '&sel=') + i.entityId : ''}` : ''}`}>{tt("git")}</Link> · <button type="button" className="link caption" onClick={() => snooze(i.id)}>{tt("ertele")}</button></td></tr>)}{items.length === 0 ? <tr><td colSpan={3} className="caption">{tt("Bugün yapacak işiniz yok")}</td></tr> : null}</tbody></table>{err ? <p className="bold">{err}</p> : null}</div>
      <div className="col-12"><CentralQueue tid={tid} /></div>
    </div></section></main>
  );
}

export function CentralQueue({ tid }: { tid: string }) {
  type Q = { id: string; kind: string; unit_code: string | null; title: string; detail: string | null; priority: string; state: string };
  const perms = usePerms(tid); const [items, setItems] = useState<Q[]>([]); const [err, setErr] = useState<string | null>(null); const [hidden, setHidden] = useState(false);
  useReconciler(async () => { setItems(checkDto<Q[]>(await api('GET', `/api/t/${tid}/corporate/queue`), DTO.queue, '/corporate/queue')); }, tid);
  const load = async () => { try { setItems(checkDto<Q[]>(await api('GET', `/api/t/${tid}/corporate/queue`), DTO.queue, '/corporate/queue')); } catch (e) { if ((e as ApiError).status === 403) setHidden(true); else setErr(describeError(e)); } };
  useEffect(() => { void load(); }, [tid]);
  const decide = async (id: string, state: 'in_review' | 'decided' | 'closed', outcome?: 'accept' | 'reject') => { const decision = prompt(outcome === 'accept' ? tt("Kabul gerekçesi (zorunlu)") : outcome === 'reject' ? tt("Ret gerekçesi (zorunlu)") : tt("Kapatma notu (karar verilmez; alttaki kayıt değişmez)")); if (!decision || decision.trim().length < 3) return; try { await commandApi(`/api/t/${tid}/corporate/queue/${id}/decide`, { decision: decision.trim(), state, ...(outcome ? { outcome } : {}) }); await load(); } catch (e) { setErr(describeError(e)); } };
  if (hidden) return null;
  return (<div className="stack"><Kicker>{tt("Bekleyen kararlar (sahipsiz birim, istisna, karşı teklif, kaynak)")}</Kicker>
    <table className="table"><thead><tr><th>{tt("Tür")}</th><th>{tt("Birim")}</th><th>{tt("Konu")}</th><th>{tt("Öncelik")}</th><th>{tt("Durum")}</th><th></th></tr></thead><tbody>{items.map(q => <tr key={q.id}><td className="caption">{trl(q.kind)}</td><td>{q.unit_code ?? ''}</td><td>{q.title}{q.detail ? <span className="caption"> · {q.detail}</span> : null}</td><td className="caption">{trl(q.priority)}</td><td className="caption">{trl(q.state)}{(q as { age_days?: number }).age_days !== undefined ? tt(" · {0} gün", (q as { age_days?: number }).age_days) : ''}</td><td>{perms.corp('centralDecision') && ['exception', 'decision', 'resource'].includes(q.kind) ? <><button type="button" className="link caption" onClick={() => decide(q.id, 'decided', 'accept')}>{tt("kabul")}</button> · <button type="button" className="link caption" onClick={() => decide(q.id, 'decided', 'reject')}>{tt("ret")}</button></> : null}{q.kind === 'upgrade' ? <span className="caption">{tt("birim sürüm kararlarıyla kapanır ·")}{' '}</span> : null}{q.kind === 'orphan' ? null : null}{perms.corp('centralDecision') && ['orphan', 'upgrade'].includes(q.kind) ? <button type="button" className="link caption" onClick={() => decide(q.id, 'closed')}>{tt("kapat")}</button> : null}</td></tr>)}{items.length === 0 ? <tr><td colSpan={6} className="caption">{tt("Açık merkezi kayıt yok")}</td></tr> : null}</tbody></table>{err ? <p className="bold">{err}</p> : null}</div>);
}

export function CohortDecisions({ tid, unitId }: { tid: string; unitId: string }) {
  type A = { id: string; item_code: string; status: string; cycle_code: string }; type Row = { ambition: A; unit: { reconciliation: string; baseline_value: string | null; local_target_value: string | null; projection_value: string | null; counterproposal_value: string | null } };
  const perms = usePerms(tid, unitId || null); const [rows, setRows] = useState<Row[]>([]); const [err, setErr] = useState<string | null>(null); const [hidden, setHidden] = useState(false);
  const load = async () => { if (!unitId) return; try { const l = await api<{ ambitions: A[] }>('GET', `/api/t/${tid}/corporate/ambitions`); const out: Row[] = []; for (const a of l.ambitions) { if (!['frozen', 'reconciling', 'reconciled'].includes(a.status)) continue; const d = await api<{ cohort: ({ unit_id: string } & Row['unit'])[] }>('GET', `/api/t/${tid}/corporate/ambitions/${a.id}`); const u = d.cohort.find(x => x.unit_id === unitId); if (u) out.push({ ambition: a, unit: u }); } setRows(out); } catch (e) { if ((e as ApiError).status === 403) setHidden(true); else setErr(describeError(e)); } };
  useEffect(() => { void load(); }, [tid, unitId]);
  const decide = async (aid: string, decision: 'exception' | 'counterproposal' | 'accept_gap') => { const reason = prompt(decision === 'exception' ? tt("İstisna gerekçesi (zorunlu)") : decision === 'counterproposal' ? tt("Karşı teklif gerekçesi (zorunlu)") : tt("Farkı kabul gerekçesi (zorunlu)")); if (!reason || reason.trim().length < 5) return; let cp: number | undefined; if (decision === 'counterproposal') { const v = prompt(tt("Karşı teklif değeri (0–100, Top Box %)")); if (v === null) return; const nv = parseNum(v, { min: 0, max: 100, required: true, label: tt("Karşı teklif") }); if (!nv.ok) { setErr(nv.error); return; } cp = nv.value ?? undefined; } try { await commandApi(`/api/t/${tid}/corporate/ambitions/${aid}/units/${unitId}/decision`, { decision, reason: reason.trim(), ...(cp !== undefined ? { counterproposalValue: cp } : {}) }); await load(); } catch (e) { setErr(describeError(e)); } };
  if (hidden || rows.length === 0) return null;
  return (<div className="stack"><Kicker>{tt("Kurumsal beklentiyle karşılaştırma · bu birim")}</Kicker><p className="caption">{tt("Yerel hedefiniz kurumsal beklentiye göre değişmez. Birim düzeyinde katkı, istisna ya da karşı teklif bildirirsiniz; kurumsal fark merkezi karar konusudur.")}</p>
    <table className="table"><thead><tr><th>{tt("Dönem · madde")}</th><th className="num">{tt("Başlangıç")}</th><th className="num">{tt("Yerel hedef")}</th><th className="num">{tt("Projeksiyon")}</th><th>{tt("Durum")}</th><th></th></tr></thead><tbody>{rows.map(r => <tr key={r.ambition.id}><td>{r.ambition.cycle_code} · {r.ambition.item_code}</td><td className="num">{r.unit.baseline_value ?? tt("gizli")}</td><td className="num">{r.unit.local_target_value ?? '—'}</td><td className="num">{r.unit.projection_value ?? '—'}</td><td className="caption">{trl(r.unit.reconciliation)}{r.unit.counterproposal_value ? tt(" (karşı teklif {0})", r.unit.counterproposal_value) : ''}</td><td>{perms.can('cohortDecision') && ['pending', 'aligned', 'gap', 'unsupported', 'contributing', 'no_local_target', 'counterproposal_rejected'].includes(r.unit.reconciliation) ? <><button type="button" className="link caption" onClick={() => decide(r.ambition.id, 'counterproposal')}>{tt("karşı teklif")}</button> · <button type="button" className="link caption" onClick={() => decide(r.ambition.id, 'exception')}>{tt("istisna")}</button> · <button type="button" className="link caption" onClick={() => decide(r.ambition.id, 'accept_gap')}>{tt("farkı kabul et")}</button></> : <span className="caption">{tt("merkezi karar bekliyor / sonuçlandı")}</span>}</td></tr>)}</tbody></table>{err ? <p className="bold">{err}</p> : null}</div>);
}
export function Deployments({ tid, unitId, cycleId }: { tid: string; unitId: string; cycleId: string }) {
  type D = { id: string; code: string; title: string; ma_version: number; cadence: string; status: string; transition_state: string; local_response: string | null; local_reason: string | null; local_action_id: string | null; local_action_title: string | null; local_action_state: string | null; unit_code: string };
  type MA = { id: string; code: string; title: string; version: number; status: string; deployments: number; executing: number; pending_upgrade: number; cadence: string };
  const perms = usePerms(tid, unitId || null); const [deps, setDeps] = useState<D[]>([]); const [mas, setMas] = useState<MA[]>([]); const [hidden, setHidden] = useState(false); const [err, setErr] = useState<string | null>(null); const [msg, setMsg] = useState<string | null>(null);
  useReconciler(async () => { if (unitId) setDeps(checkDto<D[]>(await api('GET', `/api/t/${tid}/corporate/deployments?unitId=${unitId}`), DTO.deployments, '/corporate/deployments')); else throw new Error(tt("birim yok")); }, `${tid}|${unitId}`, true);
  const load = async () => { try { setDeps(unitId ? checkDto<D[]>(await api('GET', `/api/t/${tid}/corporate/deployments?unitId=${unitId}`), DTO.deployments, '/corporate/deployments') : []); setMas(await api<MA[]>('GET', `/api/t/${tid}/corporate/master-actions`).catch(() => [])); } catch (e) { if ((e as ApiError).status === 403) setHidden(true); else setErr(describeError(e)); } };
  useEffect(() => { void load(); }, [tid, unitId]);
  const run = async (fn: () => Promise<unknown>, ok: string) => { setErr(null); setMsg(null); try { await fn(); setMsg(ok); await load(); } catch (e) { setErr(describeError(e)); } };
  const respond = async (d: D, response: 'accepted' | 'rejected') => { const reason = prompt(response === 'accepted' ? tt("Kabul gerekçesi / notu (zorunlu)") : tt("Ret gerekçesi (zorunlu)")); if (!reason || reason.trim().length < 5) return; let targetId: string | undefined; let createLocalAction = false; if (response === 'accepted') { createLocalAction = confirm(tt("Ana aksiyondan bu birim için yerel aksiyon taslağı oluşturulsun mu? (kabul edilmiş yerel hedefe bağlanır)")); if (createLocalAction) { const ts = await api<{ id: string; item_code: string; status: string }[]>('GET', `/api/t/${tid}/cycles/${cycleId}/units/${unitId}/targets`).catch(() => [] as { id: string; item_code: string; status: string }[]); const ok = ts.filter(x => ['accepted', 'active'].includes(x.status)); if (!ok.length) { setErr(tt("Kabul edilmiş yerel hedef yok; önce Hedefler ekranından hedef kabul edin")); return; } const pick = prompt(tt("Bağlanacak yerel hedef kodu: {0}", ok.map(x => x.item_code).join(', '))) ?? ''; targetId = ok.find(x => x.item_code === pick.trim())?.id ?? ok[0]!.id; } } await run(() => commandApi(`/api/t/${tid}/corporate/deployments/${d.id}/respond`, { response, reason: reason.trim(), ...(createLocalAction ? { createLocalAction: true, targetId } : {}) }), response === 'accepted' ? tt("Dağıtım kabul edildi") : tt("Dağıtım reddedildi; merkezi kuyruğa düştü")); };
  const upgrade = async (d: D, decision: 'upgrade' | 'keep_old' | 'retire') => { const reason = prompt(tt("Sürüm kararı gerekçesi")); if (!reason || reason.trim().length < 3) return; await run(() => commandApi(`/api/t/${tid}/corporate/deployments/${d.id}/upgrade`, { decision, reason: reason.trim() }), tt("Sürüm kararı kaydedildi (tarihçeli)")); };
  if (hidden) return null;
  return (<div className="stack"><Kicker>{tt("Ana aksiyon dağıtımları · bu birim")}</Kicker>
    <table className="table"><thead><tr><th>{tt("Ana aksiyon")}</th><th>{tt("Sürüm")}</th><th>{tt("Durum")}</th><th>{tt("Yerel yanıt")}</th><th>{tt("Yerel uygulama")}</th><th></th></tr></thead><tbody>{deps.map(d => <tr key={d.id}><td>{d.code} · {d.title}</td><td className="caption">{tt("v")}{d.ma_version}{d.transition_state === 'pending_upgrade' ? tt(" · yeni sürüm bekliyor") : d.transition_state === 'upgraded' ? tt(" · yükseltildi") : ''}</td><td className="caption">{trl(d.status)}</td><td className="caption">{trl(d.local_response ?? 'pending')}{d.local_reason ? ` · ${d.local_reason}` : ''}</td><td className="caption">{d.local_action_id ? <Link className="link" to={`/t/${tid}/aksiyonlar?unit=${unitId}&cycle=${cycleId}&action=${d.local_action_id}`}>{d.local_action_title ?? tt("aksiyon")} ({trl(d.local_action_state)})</Link> : '—'}</td><td>{d.status === 'active' && perms.can('resourceRequest') ? <><button type="button" className="link caption" onClick={async () => { const need = prompt(tt("Kaynak/bütçe/bağımlılık ihtiyacı")); if (!need || need.trim().length < 3) return; const reason = prompt(tt("Gerekçe (zorunlu)")); if (!reason || reason.trim().length < 5) return; const amount = prompt(tt("Tutar (TRY; boş bırakılabilir)")) ?? ''; const na = parseNum(amount, { min: 0, max: 1000000000, label: tt("Tutar") }); if (!na.ok) { setErr(na.error); return; } try { await commandApi(`/api/t/${tid}/corporate/resource-requests`, { kind: /bütçe|butce/i.test(need) ? 'budget' : /bağımlı|bagimli/i.test(need) ? 'dependency' : 'resource', deploymentId: d.id, need: need.trim(), reason: reason.trim(), ...(na.value !== null ? { amount: na.value } : {}), blocksExecution: confirm(tt("Bu ihtiyaç yerel uygulamayı bloke ediyor mu?")) }); setMsg(tt("Kaynak isteği merkezi kuyruğa düştü")); } catch (e) { setErr(describeError(e)); } }}>{tt("kaynak iste")}</button> · </> : null}{d.transition_state === 'pending_upgrade' && perms.can('upgradeDeployment') ? <><button type="button" className="link caption" onClick={() => upgrade(d, 'upgrade')}>{tt("yükselt")}</button> · <button type="button" className="link caption" onClick={() => upgrade(d, 'keep_old')}>{tt("eski sürümde kal")}</button> · <button type="button" className="link caption" onClick={() => upgrade(d, 'retire')}>{tt("emekli et")}</button></> : d.status === 'active' && perms.can('respondDeployment') && (d.local_response ?? 'pending') === 'pending' ? <><button type="button" className="link caption" onClick={() => respond(d, 'accepted')}>{tt("kabul et")}</button> · <button type="button" className="link caption" onClick={() => respond(d, 'rejected')}>{tt("reddet")}</button></> : d.status === 'active' && perms.can('respondDeployment') && !d.local_action_id ? <button type="button" className="link caption" onClick={() => respond(d, 'accepted')}>{tt("yerel aksiyon bağla")}</button> : null}</td></tr>)}{deps.length === 0 ? <tr><td colSpan={6} className="caption">{tt("Bu birime dağıtılmış ana aksiyon yok")}</td></tr> : null}</tbody></table>
    <MasterActionAdmin tid={tid} onChange={load} />
    {mas.length ? <><Kicker>{tt("Ana aksiyonlar (şirket)")}</Kicker><table className="table"><thead><tr><th>{tt("Kod")}</th><th>{tt("Başlık")}</th><th className="num">{tt("Sürüm")}</th><th>{tt("Durum")}</th><th className="num">{tt("Dağıtım / uygulama / sürüm bekleyen")}</th></tr></thead><tbody>{mas.map(m => <tr key={m.id}><td>{m.code}</td><td>{m.title}</td><td className="num">{tt("v")}{m.version}</td><td className="caption">{trl(m.status)}</td><td className="num">{m.deployments} / {m.executing} / {m.pending_upgrade}</td></tr>)}</tbody></table><p className="caption">{tt("Sürüm geçişi kararı birim düzeyinde yukarıdadır; yeni ana aksiyon, yeni sürüm ve dağıtım şirket geneli İK yöneticisi için aşağıdaki panelden yapılır.")}</p></> : null}
    {msg ? <p className="caption">{msg}</p> : null}{err ? <p className="bold">{err}</p> : null}</div>);
}

export function MasterActionAdmin({ tid, onChange }: { tid: string; onChange: () => Promise<void> }) {
  type MA = { id: string; code: string; title: string; version: number; status: string; cadence: string };
  const [me, setMe] = useState<{ profile?: string; companyWide?: boolean; realm?: string } | null>(null); const [mas, setMas] = useState<MA[]>([]); const [f, setF] = useState({ code: '', title: '', cadence: 'monthly', horizonDays: '180', supersedesId: '' }); const [dep, setDep] = useState({ masterId: '', unitType: '', codes: '' }); const [units, setUnits] = useState<{ code: string; unit_type: string; effective_from?: string; effective_to?: string | null }[]>([]); const [msg, setMsg] = useState<string | null>(null); const [err, setErr] = useState<string | null>(null);
  useEffect(() => { api<{ profile?: string; companyWide?: boolean; realm?: string }>('GET', '/api/auth/me').then(setMe).catch(() => null); api<MA[]>('GET', `/api/t/${tid}/corporate/master-actions`).then(setMas).catch(() => null); api<{ units: { code: string; unit_type: string; effective_from?: string; effective_to?: string | null }[] }>('GET', `/api/t/${tid}/org`).then(o => { const today = new Date().toISOString().slice(0, 10); setUnits(o.units.filter(u => String(u.effective_from ?? '').slice(0, 10) <= today && (!u.effective_to || String(u.effective_to).slice(0, 10) > today))); }).catch(() => null); /* yalnız bugün etkin birimler */ }, [tid]);
  const perms = usePerms(tid); if (!me || !perms.corp('publish')) return null;
  const targets = () => units.filter(u => (dep.unitType ? u.unit_type === dep.unitType : true) && (dep.codes.trim() ? dep.codes.split(',').map(x => x.trim()).filter(Boolean).includes(u.code) : true)).map(u => u.code);
  const publish = async () => { setErr(null); setMsg(null); const hz = parseNum(f.horizonDays, { min: 7, max: 730, integer: true, required: true, label: tt("Ufuk (gün)") }); if (!hz.ok) { setErr(hz.error); return; } try { const r = await commandApi<{ id: string; version: number }>(`/api/t/${tid}/corporate/master-actions`, { code: f.code.trim(), title: f.title.trim(), cadence: f.cadence, horizonDays: hz.value, ...(f.supersedesId ? { supersedesId: f.supersedesId } : {}) }); setMsg(tt("Ana aksiyon yayımlandı: {0} v{1}", f.code, r.version)); setMas(await api<MA[]>('GET', `/api/t/${tid}/corporate/master-actions`)); await onChange(); } catch (e) { setErr(describeError(e)); } };
  const deploy = async () => { setErr(null); setMsg(null); const codes = targets(); if (!codes.length) { setErr(tt("Dağıtım kapsamı boş")); return; } if (!confirm(tt("{0} birime dağıtılacak. Onaylıyor musunuz?", codes.length))) return; try { const r = await commandApi<{ deployed: number; total: number }>(`/api/t/${tid}/corporate/master-actions/${dep.masterId}/deploy`, { unitCodes: codes }); setMsg(tt("Dağıtım: {0} yeni / {1} birim (tekrar dağıtım güvenli, idempotent)", r.deployed, r.total)); await onChange(); } catch (e) { setErr(describeError(e)); } };
  const types = [...new Set(units.map(u => u.unit_type))];
  return (<div className="stack"><Kicker>{tt("Ana aksiyon yönetimi (şirket geneli İK yöneticisi)")}</Kicker>
    <div className="row"><div style={{ width: '12ch' }}><Field id="ma-code" label={tt("Kod")} value={f.code} onChange={e => setF({ ...f, code: e.target.value })} /></div><div style={{ width: '26ch' }}><Field id="ma-title" label={tt("Başlık")} value={f.title} onChange={e => setF({ ...f, title: e.target.value })} /></div><div style={{ width: '12ch' }}><Field id="ma-cad" kind="select" label={tt("Ritim")} value={f.cadence} onChange={e => setF({ ...f, cadence: e.target.value })}>{['weekly', 'biweekly', 'monthly', 'quarterly', 'once'].map(x => <option key={x} value={x}>{trl(x)}</option>)}</Field></div><div style={{ width: '10ch' }}><Field id="ma-hz" label={tt("Ufuk (gün)")} value={f.horizonDays} onChange={e => setF({ ...f, horizonDays: e.target.value })} /></div><div style={{ width: '22ch' }}><Field id="ma-sup" kind="select" label={tt("Yeni sürümü (isteğe bağlı)")} value={f.supersedesId} onChange={e => { const m = mas.find(x => x.id === e.target.value); setF({ ...f, supersedesId: e.target.value, code: m ? m.code : f.code, cadence: m ? m.cadence : f.cadence }); }}><option value="">{tt("— yeni ana aksiyon —")}</option>{mas.filter(m => m.status === 'published').map(m => <option key={m.id} value={m.id}>{m.code} {tt("v")}{m.version}</option>)}</Field></div><div><Button onClick={publish} disabled={!f.code.trim() || !f.title.trim()} disabledReason={tt("Kod, başlık ve ufuk zorunlu")}>{tt("Yayımla")}</Button></div></div>
    <div className="row"><div style={{ width: '22ch' }}><Field id="dp-ma" kind="select" label={tt("Dağıtılacak ana aksiyon")} value={dep.masterId} onChange={e => setDep({ ...dep, masterId: e.target.value })}><option value="">{tt("seçin")}</option>{mas.filter(m => m.status === 'published').map(m => <option key={m.id} value={m.id}>{m.code} {tt("v")}{m.version}</option>)}</Field></div><div style={{ width: '14ch' }}><Field id="dp-type" kind="select" label={tt("Birim tipi filtresi")} value={dep.unitType} onChange={e => setDep({ ...dep, unitType: e.target.value })}><option value="">{tt("tümü")}</option>{types.map(x => <option key={x} value={x}>{x}</option>)}</Field></div><div style={{ width: '30ch' }}><Field id="dp-codes" label={tt("Birim kodları (virgülle; boş = filtreye uyan hepsi)")} value={dep.codes} onChange={e => setDep({ ...dep, codes: e.target.value })} /></div><div><Button onClick={deploy} disabled={!perms.corp('deploy') || !dep.masterId || targets().length === 0} disabledReason={tt("Ana aksiyon ve en az bir birim gerekli")}>{tt("Dağıt (")}{targets().length} {tt("birim)")}</Button></div></div>
    <p className="caption">{tt("Önizleme:")}{' '}{targets().length} {tt("birim")}{targets().length ? ` · ${targets().slice(0, 15).join(', ')}${targets().length > 15 ? ' …' : ''}` : ''}{tt(". Aynı ana aksiyon aynı birime ikinci kez dağıtılmaz (idempotent); 400 birimlik dağıtım tek komuttur.")}</p>
    {msg ? <p className="caption">{msg}</p> : null}{err ? <p className="bold">{err}</p> : null}</div>);
}

export function OfficialAggregates({ tid, cycleId, unitId }: { tid: string; cycleId: string; unitId: string }) {
  type Ag = { code: string; official: { value: number; definitionVersion: string; status: string; source: string | null } | null; derivedEstimate: { value: number; members: number; note: string } | null; note: string | null };
  const [rows, setRows] = useState<Ag[]>([]); const [hidden, setHidden] = useState(false);
  useEffect(() => { if (!cycleId || !unitId) return; api<{ aggregates: Ag[] }>('GET', `/api/t/${tid}/cycles/${cycleId}/units/${unitId}/aggregates`).then(r => { setRows(r.aggregates); setHidden(false); }).catch(() => setHidden(true)); }, [tid, cycleId, unitId]);
  if (hidden || rows.length === 0) return null;
  return (<div className="stack"><Kicker>{tt("Endeksler · resmî HPW toplamı ve türetilmiş tahmin")}</Kicker>
    <table className="table"><thead><tr><th>{tt("Endeks")}</th><th className="num">{tt("Resmî HPW")}</th><th>{tt("Tanım sürümü · durum")}</th><th className="num">{tt("Türetilmiş tahmin")}</th><th>{tt("Not")}</th></tr></thead><tbody>{rows.map(a => <tr key={a.code}><td>{a.code}</td><td className="num">{a.official ? a.official.value : '—'}</td><td className="caption">{a.official ? `${a.official.definitionVersion} · ${trl(a.official.status)}` : tt("resmî toplam yüklenmedi")}</td><td className="num">{a.derivedEstimate ? a.derivedEstimate.value : '—'}</td><td className="caption">{a.derivedEstimate ? tt("madde ortalaması; resmî HPW sonucu değildir") : (a.note ?? '')}</td></tr>)}</tbody></table>
    <p className="caption">{tt("Resmî değer yalnız HPW’nin yüklediği toplamdır. Türetilmiş tahmin, üye maddelerin hepsi görünürse hesaplanır; gizli madde varsa üretilmez.")}</p></div>);
}
